/* ================= PRODUCT CARD ================= */
function ProductCard({ product, onClick, wishlist, toggleWishlist }) {
  const isWishlisted = wishlist?.includes(product.id);
  
  return (
    <button className="avro-card" onClick={onClick}>
      <div className="avro-card-media">
        <span className="avro-card-number" aria-hidden="true">
          {product.number}
        </span>
        <img src={product.images?.[0] || product.image} alt={product.name} loading="lazy" />
        {product.tags[0] && <span className="avro-card-tag">{product.tags[0]}</span>}
        <button 
          className="avro-wishlist-btn"
          onClick={(e) => {
            e.stopPropagation();
            toggleWishlist(product.id);
          }}
          aria-label={isWishlisted ? "Remove from wishlist" : "Add to wishlist"}
        >
          <svg width="18" height="18" viewBox="0 0 24 24" fill={isWishlisted ? "currentColor" : "none"} stroke="currentColor" strokeWidth={2}>
            <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"></path>
          </svg>
        </button>
      </div>
      <div className="avro-card-body">
        <p className="avro-card-team">{product.team}</p>
        <h3 className="avro-card-name">{product.name}</h3>
        <div className="avro-card-price-row">
          <span className="avro-card-price">{formatINR(product.price)}</span>
          <span className="avro-card-mrp">{formatINR(product.mrp)}</span>
        </div>
      </div>
    </button>
  );
}

/* ================= SHOP ================= */
function Shop({ openProduct, filter, setFilter, searchQuery, setSearchQuery, wishlist, toggleWishlist }) {
  const filters = ["All", "Club", "National", "Limited"];
  const filtered = PRODUCTS.filter((p) => {
    // Apply category filter
    let categoryMatch = true;
    if (filter === "All") categoryMatch = true;
    else if (filter === "Limited") categoryMatch = p.tags.includes("LIMITED DROP");
    else categoryMatch = p.category === filter;
    
    // Apply search filter
    let searchMatch = true;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase();
      searchMatch = 
        p.name.toLowerCase().includes(query) ||
        p.team.toLowerCase().includes(query) ||
        p.category.toLowerCase().includes(query) ||
        p.tags.some(tag => tag.toLowerCase().includes(query));
    }
    
    return categoryMatch && searchMatch;
  });
  return (
    <div className="avro-page">
      <div className="avro-page-head">
        <p className="avro-eyebrow">FULL COLLECTION</p>
        <h1 className="avro-h1">SHOP AVRO</h1>
      </div>
      <div className="avro-search-bar">
        <input
          type="text"
          placeholder="Search products, teams, categories..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="avro-search-input"
        />
      </div>
      <div className="avro-filter-row">
        {filters.map((f) => (
          <button
            key={f}
            className={"avro-filter-chip" + (filter === f ? " active" : "")}
            onClick={() => setFilter(f)}
          >
            {f}
          </button>
        ))}
      </div>
      {filtered.length === 0 ? (
        <div className="avro-empty">
          <p>No pieces found matching your criteria.</p>
          <p className="avro-empty-sub">Try adjusting your filters or search terms.</p>
        </div>
      ) : (
        <div className="avro-product-grid">
          {filtered.map((p) => (
            <ProductCard key={p.id} product={p} onClick={() => openProduct(p.id)} wishlist={wishlist} toggleWishlist={toggleWishlist} />
          ))}
        </div>
      )}
    </div>
  );
}

