/* ================= CHECKOUT ================= */
function CheckoutPage({ items, subtotal, total, discountAmount, appliedDiscount, placeOrder, goTo, user }) {
  const [form, setForm] = useState({
    name: user?.name || "",
    phone: user?.phone || "",
    gate: user?.gate || "",
    gateOther: "",
    notes: user?.address || "",
  });
  const [errors, setErrors] = useState({});

  if (items.length === 0) {
    return (
      <div className="avro-page avro-empty">
        <p>Your bag is empty — add something before checking out.</p>
        <button className="avro-btn avro-btn-primary" onClick={() => goTo("shop")}>
          Shop the drop <ChevronRight size={16} />
        </button>
      </div>
    );
  }

  function handleChange(k, v) {
    setForm((f) => ({ ...f, [k]: v }));
  }

  function validate() {
    const e = {};
    if (!form.name.trim()) e.name = "Enter your full name";
    if (!/^[6-9]\d{9}$/.test(form.phone.trim())) e.phone = "Enter a valid 10-digit phone number";
    if (!form.gate) e.gate = "Select a delivery gate";
    if (form.gate === "Others" && !form.gateOther.trim()) e.gateOther = "Tell us where to deliver";
    setErrors(e);
    return Object.keys(e).length === 0;
  }

  function handleSubmit(ev) {
    ev.preventDefault();
    if (!validate()) return;
    placeOrder(form);
  }

  return (
    <div className="avro-page">
      <div className="avro-page-head">
        <p className="avro-eyebrow">FINAL STEP</p>
        <h1 className="avro-h1">CHECKOUT</h1>
      </div>

      <form className="avro-cart-layout" onSubmit={handleSubmit}>
        <div className="avro-form-col">
          <div className="avro-form-group">
            <label>Full Name</label>
            <input
              type="text"
              value={form.name}
              onChange={(e) => handleChange("name", e.target.value)}
              placeholder="e.g. Aarav Sharma"
            />
            {errors.name && <p className="avro-error">{errors.name}</p>}
          </div>

          <div className="avro-form-group">
            <label>Phone Number</label>
            <input
              type="tel"
              value={form.phone}
              onChange={(e) => handleChange("phone", e.target.value.replace(/\D/g, "").slice(0, 10))}
              placeholder="10-digit mobile number"
            />
            {errors.phone && <p className="avro-error">{errors.phone}</p>}
          </div>

          <div className="avro-form-group">
            <label>Deliver To — VIT Gate</label>
            <div className="avro-gate-grid">
              {GATES.map((g) => (
                <button
                  type="button"
                  key={g}
                  className={"avro-gate-chip" + (form.gate === g ? " active" : "")}
                  onClick={() => handleChange("gate", g)}
                >
                  <MapPin size={13} /> {g}
                </button>
              ))}
            </div>
            {errors.gate && <p className="avro-error">{errors.gate}</p>}
            {form.gate === "Others" && (
              <input
                type="text"
                style={{ marginTop: 10 }}
                value={form.gateOther}
                onChange={(e) => handleChange("gateOther", e.target.value)}
                placeholder="Tell us where to meet you"
              />
            )}
            {errors.gateOther && <p className="avro-error">{errors.gateOther}</p>}
          </div>

          <div className="avro-form-group">
            <label>Delivery Notes (optional)</label>
            <textarea
              rows={3}
              value={form.notes}
              onChange={(e) => handleChange("notes", e.target.value)}
              placeholder="Hostel block, best time to meet, etc."
            />
          </div>
        </div>

        <div className="avro-cart-summary">
          <h3>Order Summary</h3>
          {items.map((it) => (
            <div className="avro-summary-row avro-summary-item" key={it.productId + it.size}>
              <span>
                {it.product.name} · {it.size} × {it.qty}
              </span>
              <span>{formatINR(it.product.price * it.qty)}</span>
            </div>
          ))}
          {appliedDiscount && (
            <div className="avro-summary-row avro-summary-discount">
              <span>Discount ({appliedDiscount.code})</span>
              <span>-{formatINR(discountAmount)}</span>
            </div>
          )}
          <div className="avro-summary-row avro-summary-total">
            <span>Total</span>
            <span>{formatINR(total)}</span>
          </div>
          <p className="avro-muted avro-cod-note">
            <ShieldCheck size={14} style={{ verticalAlign: "-2px", marginRight: 4 }} />
            Cash on Delivery — pay only after you inspect the product. No prepayment.
          </p>
          <button type="submit" className="avro-btn avro-btn-primary avro-btn-block">
            <MessageCircle size={16} /> Place Order
          </button>
          <p className="avro-muted" style={{ marginTop: 10, fontSize: 12 }}>
            Your order will be sent to AVRO via WhatsApp for confirmation.
          </p>
        </div>
      </form>
    </div>
  );
}

