/* ================= CSS ================= */
const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Inter:wght@400;500;600;700;800&display=swap');

.avro-root {
  --black: #0a0a0a;
  --near-black: #131313;
  --white: #ffffff;
  --off-white: #f4f4f2;
  --grey-100: #e6e6e3;
  --grey-300: #b9b9b5;
  --grey-500: #8a8a86;
  --grey-700: #4a4a48;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background: var(--white);
  color: var(--black);
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}
.avro-root * { box-sizing: border-box; }
.avro-root button { font-family: inherit; cursor: pointer; }
.avro-root input, .avro-root textarea, .avro-root select {
  font-family: inherit;
}

.avro-h1, .avro-h2, .avro-hero-title, .avro-eyebrow {
  font-family: 'Bebas Neue', 'Inter', sans-serif;
}
.avro-h1 {
  font-size: clamp(32px, 6vw, 52px);
  letter-spacing: 0.5px;
  line-height: 0.95;
  margin: 6px 0 0;
}
.avro-h2 {
  font-size: clamp(24px, 4vw, 34px);
  letter-spacing: 0.5px;
  margin: 0;
}
.avro-eyebrow {
  font-size: 12px;
  letter-spacing: 3px;
  color: var(--grey-500);
  margin: 0;
  font-weight: 600;
  font-family: 'Inter', sans-serif;
  text-transform: uppercase;
}

/* Topbar */
.avro-topbar {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--grey-100);
}
.avro-topbar-inner {
  max-width: 1240px;
  margin: 0 auto;
  padding: 14px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.avro-logo-btn { background: none; border: none; padding: 0; display: flex; align-items: center; }
.avro-logo-img { height: 45px; width: auto; display: block; max-width: 180px; object-fit: contain; }
.avro-nav-desktop { display: none; gap: 32px; }
.avro-nav-link {
  background: none; border: none; color: var(--grey-700);
  font-size: 13px; font-weight: 600; letter-spacing: 1.5px; text-transform: uppercase;
  padding: 6px 0; position: relative;
}
.avro-nav-link.active { color: var(--black); }
.avro-nav-link.active::after {
  content: ''; position: absolute; left: 0; right: 0; bottom: -3px; height: 2px; background: var(--black);
}
.avro-topbar-actions { display: flex; align-items: center; gap: 6px; }
.avro-icon-btn {
  background: none; border: none; color: var(--black);
  width: 38px; height: 38px; display: flex; align-items: center; justify-content: center;
  position: relative; border-radius: 999px;
}
.avro-icon-btn:hover { background: var(--off-white); }
.avro-cart-badge {
  position: absolute; top: 2px; right: 2px; background: var(--black); color: var(--white);
  font-size: 10px; font-weight: 700; min-width: 16px; height: 16px; border-radius: 999px;
  display: flex; align-items: center; justify-content: center; padding: 0 3px;
}
.avro-menu-btn { display: flex; }
.avro-mobile-menu {
  display: flex; flex-direction: column; padding: 8px 24px 18px;
  border-top: 1px solid var(--grey-100);
}
.avro-mobile-link {
  background: none; border: none; text-align: left; padding: 12px 0;
  font-size: 15px; font-weight: 600; letter-spacing: 1px; text-transform: uppercase;
  color: var(--grey-700); border-bottom: 1px solid var(--grey-100);
}
.avro-mobile-link.active { color: var(--black); }

@media (min-width: 860px) {
  .avro-nav-desktop { display: flex; }
  .avro-menu-btn { display: none; }
  .avro-mobile-menu { display: none; }
  .avro-logo-img { height: 60px; max-width: none; }
  .avro-hero { padding: 90px 24px 70px; min-height: 78vh; }
  .avro-hero-title { font-size: clamp(56px, 13vw, 128px); letter-spacing: 1px; }
  .avro-hero-sub { max-width: 440px; font-size: 15px; margin: 0 0 32px; }
  .avro-btn { padding: 14px 26px; font-size: 13px; letter-spacing: 1.5px; }
  .avro-section { padding: 64px 24px; }
  .avro-product-grid { grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 22px; }
  .avro-card-body { padding: 14px 16px 18px; }
  .avro-card-team { font-size: 11px; letter-spacing: 1px; margin: 0 0 4px; }
  .avro-card-name { font-size: 15px; margin: 0 0 10px; }
  .avro-footer-logo { height: 36px; }
}

/* Hero */
.avro-hero {
  position: relative;
  background: var(--black);
  color: var(--white);
  padding: 60px 20px 50px;
  overflow: hidden;
  display: flex;
  align-items: center;
  min-height: 65vh;
}
.avro-hero-number {
  position: absolute;
  right: -4vw;
  top: 50%;
  transform: translateY(-50%);
  font-family: 'Bebas Neue', sans-serif;
  font-size: 62vw;
  line-height: 1;
  color: rgba(255,255,255,0.045);
  pointer-events: none;
  user-select: none;
}
.avro-hero-content { max-width: 1240px; margin: 0 auto; width: 100%; position: relative; z-index: 1; }
.avro-hero .avro-eyebrow { color: var(--grey-300); }
.avro-hero-title {
  font-size: clamp(36px, 10vw, 128px);
  line-height: 0.9;
  margin: 8px 0 18px;
  letter-spacing: 0.5px;
}
.avro-hero-sub {
  color: var(--grey-300); max-width: 100%; font-size: 14px; line-height: 1.5; margin: 0 0 24px;
}
.avro-hero-actions { display: flex; gap: 14px; flex-wrap: wrap; }

.avro-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 12px 20px; font-size: 12px; font-weight: 700; letter-spacing: 1px;
  text-transform: uppercase; border-radius: 2px; border: 1.5px solid transparent;
  text-decoration: none; transition: transform .15s ease, opacity .15s ease;
}
.avro-btn:active { transform: scale(0.98); }
.avro-btn-primary { background: var(--white); color: var(--black); }
.avro-hero .avro-btn-primary:hover, .avro-btn-primary:hover { opacity: 0.85; }
.avro-btn-ghost { background: transparent; color: var(--white); border-color: rgba(255,255,255,0.4); }
.avro-btn-ghost:hover { border-color: var(--white); }
.avro-btn-outline { background: transparent; color: var(--black); border-color: var(--black); }
.avro-btn-outline:hover { background: var(--black); color: var(--white); }
.avro-btn-block { width: 100%; }

/* Strip */
.avro-strip {
  display: flex; flex-wrap: wrap; justify-content: center; gap: 10px;
  padding: 20px 24px; background: var(--off-white); border-bottom: 1px solid var(--grey-100);
}
.avro-strip-item {
  display: flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 600;
  letter-spacing: 1px; text-transform: uppercase; color: var(--grey-700); padding: 6px 14px;
}

/* Sections */
.avro-section { max-width: 1240px; margin: 0 auto; padding: 48px 20px; }
.avro-section-head {
  display: flex; align-items: flex-end; justify-content: space-between; margin-bottom: 28px; gap: 12px; flex-wrap: wrap;
}
.avro-textlink {
  background: none; border: none; font-size: 12px; font-weight: 700; letter-spacing: 1.5px;
  text-transform: uppercase; color: var(--black); display: inline-flex; align-items: center; gap: 4px;
}
.avro-textlink:hover { text-decoration: underline; }

/* Product grid & card */
.avro-product-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 16px;
}
.avro-card {
  background: var(--white); border: 1px solid var(--grey-100); border-radius: 4px;
  overflow: hidden; text-align: left; padding: 0; display: flex; flex-direction: column;
  transition: border-color .2s ease, transform .2s ease;
}
.avro-card:hover { border-color: var(--black); transform: translateY(-2px); }
.avro-card-media {
  position: relative; aspect-ratio: 4/5; background: var(--off-white); overflow: hidden;
}
.avro-card-media img { width: 100%; height: 100%; object-fit: cover; object-position: top center; }
.avro-wishlist-btn {
  position: absolute; top: 12px; right: 12px; width: 36px; height: 36px;
  background: rgba(255, 255, 255, 0.9); border: none; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer; transition: all .2s ease; color: var(--black);
  z-index: 2;
}
.avro-wishlist-btn:hover { background: var(--white); transform: scale(1.1); }
.avro-wishlist-btn:active { transform: scale(0.95); }
.avro-card-number {
  position: absolute; top: 8px; left: 10px; font-family: 'Bebas Neue', sans-serif;
  font-size: 46px; color: rgba(0,0,0,0.1); z-index: 1; line-height: 1;
}
.avro-card-number-lg { font-size: 110px; top: -10px; left: -6px; }
.avro-card-tag {
  position: absolute; top: 10px; right: 10px; background: var(--black); color: var(--white);
  font-size: 10px; font-weight: 700; letter-spacing: 1px; padding: 5px 9px; border-radius: 2px;
}
.avro-card-body { padding: 12px 14px 16px; }
.avro-card-team { font-size: 10px; letter-spacing: 0.5px; text-transform: uppercase; color: var(--grey-500); margin: 0 0 3px; }
.avro-card-name { font-size: 16px; font-weight: 700; margin: 0 0 10px; letter-spacing: 0.2px; }
.avro-card-price-row { display: flex; align-items: baseline; gap: 8px; }
.avro-card-price { font-size: 17px; font-weight: 800; }
.avro-card-mrp { font-size: 13px; color: var(--grey-500); text-decoration: line-through; }
.avro-price-lg { font-size: 30px; font-weight: 800; }
.avro-off-badge { background: var(--off-white); color: var(--black); font-size: 11px; font-weight: 700; padding: 4px 8px; border-radius: 2px; }

/* Manifesto */
.avro-manifesto { background: var(--off-white); padding: 48px 20px; }
.avro-manifesto-grid {
  max-width: 1240px; margin: 0 auto; display: grid; grid-template-columns: 1fr; gap: 24px;
}
.avro-manifesto-copy { font-size: 16px; line-height: 1.7; color: var(--grey-700); max-width: 560px; }
.avro-tags-row { max-width: 1240px; margin: 32px auto 0; display: flex; flex-wrap: wrap; gap: 10px; }
.avro-pill {
  border: 1px solid var(--grey-300); color: var(--grey-700); font-size: 11px; font-weight: 700;
  letter-spacing: 1.5px; padding: 8px 14px; border-radius: 999px; text-transform: uppercase;
}
.avro-pill-dark { background: var(--black); color: var(--white); border-color: var(--black); }
@media (min-width: 860px) {
  .avro-manifesto-grid { grid-template-columns: 1fr 1fr; align-items: center; }
  .avro-manifesto { padding: 70px 24px; }
  .avro-page { padding: 48px 24px 90px; }
  .avro-search-input { padding: 14px 18px; }
  .avro-filter-chip { padding: 9px 18px; font-size: 12px; letter-spacing: 1px; }
}

.avro-review-strip { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px,1fr)); gap: 18px; }

/* Page shell */
.avro-page { max-width: 1240px; margin: 0 auto; padding: 36px 20px 60px; min-height: 50vh; }
.avro-page-head { margin-bottom: 30px; }

/* Filters */
.avro-search-bar { margin: 24px 0 20px; }
.avro-search-input {
  width: 100%; border: 1.5px solid var(--grey-300); border-radius: 4px; padding: 12px 16px;
  font-size: 14px; background: var(--white); color: var(--black); transition: border-color .2s ease;
}
.avro-search-input:focus { outline: none; border-color: var(--black); }
.avro-filter-row { display: flex; flex-wrap: wrap; gap: 10px; margin: 24px 0 32px; }
.avro-filter-chip {
  border: 1.5px solid var(--grey-300); background: transparent; padding: 8px 14px; border-radius: 999px;
  font-size: 11px; font-weight: 700; letter-spacing: 0.5px; text-transform: uppercase; color: var(--grey-700);
}
.avro-filter-chip.active { background: var(--black); border-color: var(--black); color: var(--white); }

.avro-empty { text-align: center; padding: 60px 20px; color: var(--grey-700); }
.avro-empty-sub { color: var(--grey-500); font-size: 13px; margin-top: 4px; }
.avro-empty-inline { padding: 30px 10px; text-align: left; }

/* Product page */
.avro-back {
  background: none; border: none; display: inline-flex; align-items: center; gap: 4px;
  font-size: 12px; font-weight: 700; letter-spacing: 1px; text-transform: uppercase;
  color: var(--grey-700); margin-bottom: 22px;
}
.avro-back:hover { color: var(--black); }
.avro-product-grid-2 { display: grid; grid-template-columns: 1fr; gap: 30px; }
.avro-product-media {
  position: relative; background: var(--off-white); border-radius: 4px; overflow: hidden;
  aspect-ratio: 4/5;
}
.avro-product-media img { width: 100%; height: 100%; object-fit: cover; object-position: top center; position: relative; z-index: 1; }
.avro-image-nav {
  position: absolute; top: 50%; transform: translateY(-50%); z-index: 10;
  background: rgba(255, 255, 255, 0.9); border: none; border-radius: 50%;
  width: 40px; height: 40px; display: flex; align-items: center; justify-content: center;
  cursor: pointer; transition: all 0.2s; color: var(--black);
}
.avro-image-nav:hover { background: var(--white); box-shadow: 0 2px 8px rgba(0,0,0,0.15); }
.avro-image-nav-prev { left: 12px; }
.avro-image-nav-next { right: 12px; }
.avro-image-dots {
  position: absolute; bottom: 12px; left: 50%; transform: translateX(-50%);
  display: flex; gap: 8px; z-index: 10;
}
.avro-image-dot {
  width: 8px; height: 8px; border-radius: 50%; border: none; background: rgba(255, 255, 255, 0.5);
  cursor: pointer; transition: all 0.2s;
}
.avro-image-dot:hover { background: rgba(255, 255, 255, 0.8); }
.avro-image-dot.active { background: var(--white); width: 20px; border-radius: 4px; }
.avro-body-copy { font-size: 15px; line-height: 1.7; color: var(--grey-700); margin: 0 0 26px; }
.avro-label-row { font-size: 11px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--grey-700); display: block; margin-bottom: 10px; }
.avro-size-block { margin-bottom: 22px; }
.avro-size-grid { display: flex; gap: 8px; flex-wrap: wrap; }
.avro-size-chip {
  width: 42px; height: 42px; border: 1.5px solid var(--grey-300); background: var(--white);
  font-weight: 700; font-size: 12px; border-radius: 4px;
}
.avro-size-chip.active { background: var(--black); border-color: var(--black); color: var(--white); }
.avro-qty-row { margin-bottom: 26px; }
.avro-qty-stepper {
  display: inline-flex; align-items: center; border: 1.5px solid var(--grey-300); border-radius: 4px; overflow: hidden;
}
.avro-qty-stepper button { background: var(--off-white); border: none; width: 32px; height: 32px; display: flex; align-items: center; justify-content: center; }
.avro-qty-stepper span { width: 32px; text-align: center; font-weight: 700; font-size: 13px; }
.avro-product-actions { display: flex; gap: 12px; margin-bottom: 30px; flex-wrap: wrap; }
.avro-product-actions .avro-btn { flex: 1 1 160px; }
.avro-detail-list { list-style: none; padding: 0; margin: 0 0 26px; display: grid; gap: 10px; }
.avro-detail-list li { display: flex; align-items: flex-start; gap: 8px; font-size: 13.5px; color: var(--grey-700); }
.avro-info-strip { display: flex; flex-direction: column; gap: 10px; border-top: 1px solid var(--grey-100); padding-top: 18px; }
.avro-info-strip div { display: flex; align-items: center; gap: 8px; font-size: 13px; color: var(--grey-700); }
.avro-error { color: #b00020; font-size: 12px; margin: 6px 0 0; font-weight: 600; }

@media (min-width: 860px) {
  .avro-product-grid-2 { grid-template-columns: 0.9fr 1fr; gap: 56px; }
  .avro-size-chip { width: 46px; height: 46px; font-size: 13px; }
  .avro-qty-stepper button { width: 34px; height: 34px; }
  .avro-qty-stepper span { width: 34px; font-size: 14px; }
  .avro-cart-item { grid-template-columns: 84px 1fr auto; gap: 16px; padding: 14px; }
  .avro-cart-item img { width: 84px; height: 100px; }
}

/* Cart & checkout */
.avro-cart-layout { display: grid; grid-template-columns: 1fr; gap: 30px; align-items: start; }
.avro-cart-items { display: flex; flex-direction: column; gap: 16px; }
.avro-cart-item {
  display: grid; grid-template-columns: 70px 1fr auto; gap: 12px; padding: 12px; border: 1px solid var(--grey-100); border-radius: 4px; align-items: center;
}
.avro-cart-item img { width: 70px; height: 84px; object-fit: cover; object-position: top center; border-radius: 3px; background: var(--off-white); }
.avro-cart-item-info h3 { font-size: 14px; margin: 0 0 4px; font-weight: 700; }
.avro-cart-item-price { font-weight: 700; margin: 4px 0 0; }
.avro-cart-item-actions { display: flex; flex-direction: column; align-items: flex-end; gap: 10px; }
.avro-remove-btn { background: none; border: none; color: var(--grey-500); }
.avro-remove-btn:hover { color: #b00020; }
.avro-muted { color: var(--grey-500); font-size: 13px; margin: 0; }

.avro-cart-summary {
  border: 1.5px solid var(--black); border-radius: 4px; padding: 18px; position: sticky; top: 90px;
}
.avro-cart-summary h3 { font-size: 15px; letter-spacing: 1px; text-transform: uppercase; margin: 0 0 18px; }
.avro-summary-row { display: flex; justify-content: space-between; font-size: 14px; padding: 8px 0; color: var(--grey-700); }
.avro-summary-item { font-size: 12.5px; }
.avro-summary-discount { color: var(--green-600); }
.avro-summary-total { border-top: 1px solid var(--grey-100); margin-top: 6px; padding-top: 14px; font-weight: 800; font-size: 16px; color: var(--black); }
.avro-cod-note { margin: 12px 0 16px; line-height: 1.5; }
.avro-discount-section { margin: 16px 0; }
.avro-discount-input { display: flex; gap: 8px; }
.avro-discount-input input { flex: 1; border: 1.5px solid var(--grey-300); border-radius: 4px; padding: 10px 12px; font-size: 14px; }
.avro-discount-input button { white-space: nowrap; padding: 10px 16px; }
.avro-discount-remove { width: 100%; padding: 8px; font-size: 13px; color: var(--grey-600); background: none; border: 1px dashed var(--grey-300); border-radius: 4px; cursor: pointer; margin: 12px 0; transition: all .2s; }
.avro-discount-remove:hover { border-color: var(--black); color: var(--black); }

.avro-form-col { display: flex; flex-direction: column; gap: 20px; }
.avro-form-group label { display: block; font-size: 11px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; color: var(--grey-700); margin-bottom: 8px; }
.avro-form-group input, .avro-form-group textarea, .avro-form-group select {
  width: 100%; border: 1.5px solid var(--grey-300); border-radius: 4px; padding: 10px 12px; font-size: 14px; background: var(--white); color: var(--black);
}
.avro-form-group input:focus, .avro-form-group textarea:focus, .avro-form-group select:focus {
  outline: none; border-color: var(--black);
}
.avro-form-group input:disabled { background: var(--off-white); color: var(--grey-500); }
.avro-gate-grid { display: flex; flex-wrap: wrap; gap: 8px; }
.avro-gate-chip {
  display: inline-flex; align-items: center; gap: 6px; border: 1.5px solid var(--grey-300); background: var(--white);
  padding: 8px 12px; border-radius: 999px; font-size: 11.5px; font-weight: 600; color: var(--grey-700);
}
.avro-gate-chip.active { background: var(--black); border-color: var(--black); color: var(--white); }

@media (min-width: 900px) {
  .avro-cart-layout { grid-template-columns: 1fr 360px; }
  .avro-cart-summary { padding: 24px; }
  .avro-form-group input, .avro-form-group textarea, .avro-form-group select { padding: 12px 14px; }
  .avro-gate-chip { padding: 9px 14px; font-size: 12.5px; }
  .avro-confirmation { padding-top: 60px; }
  .avro-confirm-card { padding: 20px 24px; }
}

/* Confirmation */
.avro-confirmation { text-align: center; padding-top: 40px; }
.avro-confirm-icon {
  width: 64px; height: 64px; border-radius: 999px; background: var(--black); color: var(--white);
  display: flex; align-items: center; justify-content: center; margin: 0 auto 20px;
}
.avro-confirm-card {
  max-width: 380px; margin: 0 auto; border: 1px solid var(--grey-100); border-radius: 4px; padding: 16px 20px; text-align: left;
}

/* Reviews */
.avro-rating-summary { display: flex; align-items: center; gap: 16px; margin-top: 20px; }
.avro-rating-num { font-family: 'Bebas Neue', sans-serif; font-size: 44px; line-height: 1; }
.avro-stars { display: flex; gap: 2px; color: var(--black); }
.avro-reviews-layout { display: grid; grid-template-columns: 1fr; gap: 32px; }
.avro-review-list { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px,1fr)); gap: 18px; align-content: start; }
.avro-review-card { border: 1px solid var(--grey-100); border-radius: 4px; padding: 18px; display: flex; flex-direction: column; gap: 10px; }
.avro-review-card.compact { background: var(--off-white); border-color: transparent; }
.avro-review-text { font-size: 14px; line-height: 1.55; color: var(--black); margin: 0; flex: 1; }
.avro-review-meta { display: flex; flex-direction: column; gap: 2px; }
.avro-review-name { font-weight: 700; font-size: 13px; }
.avro-review-form { border: 1.5px solid var(--black); border-radius: 4px; padding: 24px; height: fit-content; }
.avro-review-form h3 { font-size: 15px; letter-spacing: 1px; text-transform: uppercase; margin: 0 0 18px; }
.avro-review-form .avro-form-group { margin-bottom: 16px; }
.avro-star-picker { display: flex; gap: 4px; color: var(--black); }
.avro-star-picker button { background: none; border: none; padding: 2px; }
.avro-success-text { color: var(--black); font-weight: 700; font-size: 13px; margin: 12px 0 0; text-align: center; }

@media (min-width: 960px) {
  .avro-reviews-layout { grid-template-columns: 1fr 360px; }
}

/* Account */
.avro-account-grid { display: grid; grid-template-columns: 1fr; gap: 28px; }
.avro-account-card { border: 1.5px solid var(--black); border-radius: 4px; padding: 26px; text-align: center; height: fit-content; }
.avro-account-avatar {
  width: 60px; height: 60px; border-radius: 999px; background: var(--off-white); display: flex; align-items: center; justify-content: center; margin: 0 auto 14px;
}
.avro-account-card h3 { margin: 0 0 2px; font-size: 17px; }
.avro-account-detail { display: flex; align-items: center; justify-content: center; gap: 6px; font-size: 13px; color: var(--grey-700); margin-top: 10px; }
.avro-signout { display: flex; align-items: center; gap: 6px; justify-content: center; width: 100%; margin-top: 14px; color: var(--grey-500); }
.avro-orders-heading { font-size: 15px; letter-spacing: 1px; text-transform: uppercase; margin: 0 0 16px; }
.avro-order-list { display: flex; flex-direction: column; gap: 14px; }
.avro-order-card { border: 1px solid var(--grey-100); border-radius: 4px; padding: 16px; }
.avro-order-head { display: flex; justify-content: space-between; font-weight: 700; font-size: 13px; }
.avro-order-foot { display: flex; justify-content: space-between; align-items: center; font-weight: 700; margin-top: 8px; }
.avro-order-status { font-size: 11px; font-weight: 600; color: var(--grey-500); text-transform: uppercase; letter-spacing: 0.5px; }
.avro-status-select { font-size: 11px; font-weight: 600; color: var(--grey-500); text-transform: uppercase; letter-spacing: 0.5px; border: 1px solid var(--grey-200); border-radius: 4px; padding: 4px 8px; background: var(--white); cursor: pointer; }
.avro-status-select:hover { border-color: var(--black); }

@media (min-width: 860px) {
  .avro-account-grid { grid-template-columns: 300px 1fr; }
}

/* Auth */
.avro-auth-page { display: flex; flex-direction: column; align-items: center; }
.avro-signin-block { text-align: center; max-width: 460px; padding-top: 30px; }
.avro-signin-block .avro-body-copy { margin: 14px auto 26px; }
.avro-google-btn {
  display: inline-flex; align-items: center; gap: 10px; background: var(--white); color: #3c4043;
  border: 1.5px solid var(--grey-300); border-radius: 4px; padding: 12px 24px; font-size: 14px; font-weight: 600;
}
.avro-google-btn:hover { box-shadow: 0 1px 6px rgba(0,0,0,0.15); }
.avro-preview-note { margin-top: 14px; font-size: 11.5px; max-width: 320px; margin-left: auto; margin-right: auto; }
.avro-google-modal {
  max-width: 340px; width: 100%; border: 1px solid var(--grey-100); border-radius: 8px; padding: 28px 24px;
  box-shadow: 0 8px 30px rgba(0,0,0,0.1); margin-top: 20px;
}
.avro-google-head { display: flex; align-items: center; gap: 10px; font-size: 16px; font-weight: 600; color: #3c4043; margin-bottom: 6px; }
.avro-google-sub { font-size: 13px; color: var(--grey-500); margin: 0 0 18px; }
.avro-google-account { display: flex; align-items: center; gap: 12px; width: 100%; background: none; border: none; padding: 10px 4px; border-radius: 4px; text-align: left; }
.avro-google-account:hover { background: var(--off-white); }
.avro-google-avatar { width: 34px; height: 34px; border-radius: 999px; background: var(--black); color: var(--white); display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 14px; flex-shrink: 0; }
.avro-google-account p { margin: 0; font-size: 13.5px; font-weight: 600; color: var(--black); }
.avro-google-account span { font-size: 12px; color: var(--grey-500); }
.avro-google-manual { display: flex; gap: 8px; margin: 14px 0 10px; }
.avro-google-manual input { flex: 1; border: 1.5px solid var(--grey-300); border-radius: 4px; padding: 9px 10px; font-size: 13px; }
.avro-auth-card { max-width: 460px; width: 100%; border: 1.5px solid var(--black); border-radius: 4px; padding: 26px; margin-top: 10px; }
.avro-auth-card .avro-form-group { margin-bottom: 16px; }

/* Footer */
.avro-footer { background: var(--black); color: var(--grey-300); padding: 56px 24px 24px; margin-top: 40px; }
.avro-footer-top { max-width: 1240px; margin: 0 auto; display: grid; grid-template-columns: 1fr; gap: 36px; padding-bottom: 36px; border-bottom: 1px solid rgba(255,255,255,0.1); }
.avro-footer-brand p { font-family: 'Bebas Neue', sans-serif; letter-spacing: 3px; color: var(--white); margin: 10px 0 0; font-size: 14px; }
.avro-footer-logo { height: 40px; filter: none; }
.avro-footer-links { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.avro-footer-links h4 { color: var(--white); font-size: 12px; letter-spacing: 1.5px; text-transform: uppercase; margin: 0 0 14px; }
.avro-footer-links button, .avro-footer-links a { display: block; background: none; border: none; color: var(--grey-300); font-size: 13px; text-align: left; padding: 6px 0; text-decoration: none; }
.avro-footer-links a { display: inline-flex; align-items: center; gap: 6px; }
.avro-footer-links button:hover, .avro-footer-links a:hover { color: var(--white); }
.avro-footer-bottom { max-width: 1240px; margin: 0 auto; padding-top: 20px; display: flex; flex-wrap: wrap; justify-content: space-between; gap: 8px; font-size: 11.5px; color: var(--grey-500); }

@media (min-width: 700px) {
  .avro-footer-top { grid-template-columns: 1fr 2fr; }
}

/* Toast */
.avro-toast {
  position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%);
  background: var(--black); color: var(--white); padding: 12px 20px; border-radius: 999px;
  display: flex; align-items: center; gap: 8px; font-size: 13px; font-weight: 600; z-index: 100;
  box-shadow: 0 8px 24px rgba(0,0,0,0.25);
}
`;
